 UPDATE population_top3000_202608_202609_v1.acquisition_control SET next_provider_at=clock_timestamp()-interval '1 second' WHERE singleton;
 t0:=clock_timestamp();c:=population_top3000_202608_202609_v1.oq6_wake(aid,tok,d->>'worker_sha256');dt:=extract(epoch FROM clock_timestamp()-t0);maxwake:=greatest(maxwake,dt);IF dt>4 THEN RAISE EXCEPTION 'TEST_PRODUCTION_WAKE_RPC_OVER_4S %',dt;END IF;IF c->>'state'<>'CLAIMED' THEN RAISE EXCEPTION 'TEST_FINITE100_CLAIM % %',i,c;END IF;
 b:=jsonb_build_object('status','OK','results',jsonb_build_object('ticker',c#>>'{request,ticker}','name','SYNTHETIC_NOT_PROVIDER_FACT'))::text;h:=encode(sha256(convert_to(b,'UTF8')),'hex');rec:=jsonb_build_object('body_base64',encode(convert_to(b,'UTF8'),'base64'),'sha256',h,'bytes',octet_length(b),'http_status',200,'physical_http_count',1,'representation','FETCH_RESPONSE_BODY_BYTES_NOT_ORIGINAL_HTTP_WIRE');
 x:=population_top3000_202608_202609_v1.oq6_spool_save(c#>>'{request,request_key}',c->>'token',rec::text,d->>'worker_sha256');t0:=clock_timestamp();x:=population_top3000_202608_202609_v1.oq6_consume(c#>>'{request,request_key}',aid);dt:=extract(epoch FROM clock_timestamp()-t0);maxconsume:=greatest(maxconsume,dt);IF dt>4 THEN RAISE EXCEPTION 'TEST_PRODUCTION_CONSUME_RPC_OVER_4S %',dt;END IF;IF x->>'state'<>'POINT_RETAINED' THEN RAISE EXCEPTION 'TEST_FINITE100_CONSUME % %',i,x;END IF;
